@SubscribeEvent
    public static void finishEating(LivingEntityUseItemEvent.Finish event) {
        var entity = event.getEntity();
        //This won't account for cake blocks, but that would require more invasive mixins to detect so this is fine
        if (!entity.level.isClientSide) {
            var food = event.getItem().getFoodProperties(entity);
            if (food != null) {
                var gluttony = entity.getEffect(MobEffectRegistry.GLUTTONY);
                if (gluttony != null) {
                    var pmg = MagicData.getPlayerMagicData(entity);
                    pmg.addMana(food.nutrition() * ratioForAmplifier(gluttony.getAmplifier()));
                    if (entity instanceof ServerPlayer serverPlayer) {
                        PacketDistributor.sendToPlayer(serverPlayer, new SyncManaPacket(pmg));
                    }
                }
            }
        }
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        entity.addEffect(new MobEffectInstance(MobEffectRegistry.GLUTTONY, (int) (getSpellPower(spellLevel, entity) * 20), spellLevel - 1, false, false, true));
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

@Inject(method = "canEat", at = @At(value = "RETURN"), cancellable = true)
    void canEatForGluttony(boolean pCanAlwaysEat, CallbackInfoReturnable<Boolean> cir) {
        if (((Player) (Object) this).hasEffect(MobEffectRegistry.GLUTTONY)) {
            cir.setReturnValue(true);
        }
    }

public static float ratioForAmplifier(int amplifier) {
        return (4 + amplifier) * .5f;
    }

public void addMana(float mana) {
        setMana(this.mana + mana);
    }

public static void handle(SyncManaPacket packet, IPayloadContext context) {
        context.enqueueWork(() -> {
            ClientMagicData.setMana(packet.playerMana);
        });
    }
